// === Tab: mySketch ===
let vs = ` 
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main () {
vTexCoord = aTexCoord;
vec4 correct = vec4(aPosition,1.0);
correct.xy = correct.xy*2.0 - 1.0;
gl_Position = correct;
}
`
let maxPoints = 100

let fs = `
precision highp float;
varying vec2 vTexCoord;
uniform vec2 points[${maxPoints}];
uniform float time;
uniform int pointsLen;
void main() {
vec2 coord = vTexCoord;
vec3 col = vec3(0.0);
for (int i = 0; i < ${maxPoints}; i++) {
	vec3 tempCol = vec3(0.0);
	float dist = distance(points[i],coord);
	if (i > pointsLen) {
		break;
}
  if ( dist <.1) {
		tempCol.r  = (1.0- dist*10.0) - mod(time,100.0)/100.0;
		tempCol.g = (1.0 - dist*10.0)*coord.x - mod(time,100.0)/100.0;
		tempCol.b = (1.0 - dist*10.0)*coord.y - mod(time,100.0)/100.0;
	}
 if (tempCol.r > 0.0) {
	col.r += tempCol.r;
}
if (tempCol.g > 0.0) {
	col.g += tempCol.g;
}
if (tempCol.b > 0.0) {
	col.b += tempCol.b;
}
}
gl_FragColor= vec4(col,1.0);
}
`
p5.disableFriendlyErrors = true;
let myshader
let points = [];

function preload() {
	myshader = createShader(vs, fs);
}

function setup() {
	pixelDensity(1)
	createCanvas(windowWidth, windowHeight,WEBGL);

	shader(myshader)

console.log(points)
	background(100);
	noStroke()
	//frameRate(2)draw points to the screen and fade them with glsl
}

function draw() {
	myshader.setUniform("points",points)
	myshader.setUniform("pointsLen",points.length)
	myshader.setUniform("time",frameCount)
	//console.log((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/windowWidth)
	if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))&& points.length < maxPoints-2) {
		points.push((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/windowWidth)
		points.push(1-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/windowHeight)	
	}
	if (frameCount %10 == 0 && points.length > 0) {
		console.log(points)
		points = points.slice(5)
	}
	myshader.setUniform("mouse",[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/windowWidth,1-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/windowHeight])
	rect(0,0,windowWidth,windowHeight)
}

